// Search AUTHORITATIVE public sources only (Azure OpenAI Responses API, web_search tool, domain allow-list).
// The documents stay the source of truth; this tool covers what they can't: current regulations, recent changes,
// best practices. Edit the allow-list here (max 20 domains).
const ALLOWED_DOMAINS = ["epa.gov", "ecfr.gov", "federalregister.gov", "fema.gov", "usace.army.mil", "nrcs.usda.gov", "fhwa.dot.gov", "usgs.gov", "noaa.gov"];  // add your state environmental agency, state regulations site and local public-works domains
const LOCATION = { type: 'approximate', country: 'US' };  // optionally add region: '<your state>'
const query = String($json.query ?? '').trim();
return [{ json: { query, body: {
  model: 'gpt-5.4-mini',
  reasoning: { effort: 'low' },
  max_output_tokens: 2500,
  instructions: 'You research current public regulations, standards and best practices for engineering staff. ' +
    'Use only what the web search returns. Be concise (at most 250 words): key requirements as bullets, each with its ' +
    'source and, where the source shows it, the regulation or document date / effective date. If sources disagree or ' +
    'nothing authoritative is found, say so plainly.',
  input: query,
  tools: [{ type: 'web_search', filters: { allowed_domains: ALLOWED_DOMAINS }, user_location: LOCATION }],
} } }];

// Hand the agent the findings plus a clean source list (title + link) and today's date, so it can label them.
const r = $json;
const today = new Date().toISOString().slice(0, 10);
if (r.error || !Array.isArray(r.output)) {
  const msg = r.error?.message ?? r.error ?? 'no response';
  return [{ json: { web_findings: `Web search failed: ${String(msg).slice(0, 200)}`, sources: [], retrieved: today } }];
}
let text = '';
const sources = new Map();
for (const o of r.output) {
  for (const c of o.content ?? []) {
    if (c.type !== 'output_text') continue;
    text += c.text;
    for (const a of c.annotations ?? []) {
      if (a.type === 'url_citation' && a.url) sources.set(a.url.split('?utm_')[0], a.title || a.url);
    }
  }
}
return [{ json: {
  web_findings: text.trim() || 'No authoritative web results found.',
  sources: [...sources].map(([url, title]) => ({ title, url })),
  retrieved: today,
  note: 'Public web sources (allow-listed) — verify before relying; the documents remain the organization standard.',
} }];
